  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --card: rgba(255, 255, 255, 0.9);
      --text: #122033;
      --muted: #5d6b82;
      --primary: #2563eb;
      --primary-soft: #dbeafe;
      --border: #d7e0eb;
      --shadow: 0 18px 40px rgba(18, 32, 51, 0.08);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, #e0f2fe 0, transparent 30%),
        radial-gradient(circle at top right, #dbeafe 0, transparent 28%),
        var(--bg);
      color: var(--text);
      min-height: 100vh;
      padding: 32px 16px;
    }

    .page {
      max-width: 920px;
      margin: 0 auto;
    }

    .hero {
      margin-bottom: 24px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 12px;
      border-radius: 999px;
      background: var(--primary-soft);
      color: var(--primary);
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.02em;
      margin-bottom: 14px;
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(2rem, 4vw, 3.25rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .subtitle {
      margin: 0;
      max-width: 60ch;
      color: var(--muted);
      font-size: 1.02rem;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      background: var(--card);
      border: 1px solid rgba(215, 224, 235, 0.9);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 22px;
      backdrop-filter: blur(10px);
    }

    .question-title {
      margin: 0 0 8px;
      font-size: 1.08rem;
      font-weight: 700;
    }

    .help-text {
      margin: 0 0 16px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .choices {
      display: grid;
      gap: 12px;
    }

    .choice {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 14px 16px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: #fff;
      transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
      cursor: pointer;
    }

    .choice:hover {
      transform: translateY(-1px);
      border-color: #b6c7df;
      box-shadow: 0 10px 24px rgba(18, 32, 51, 0.06);
    }

    .choice input {
      margin-top: 3px;
      width: 18px;
      height: 18px;
      accent-color: var(--primary);
      flex: 0 0 auto;
    }

    .choice span {
      line-height: 1.45;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
      padding-top: 6px;
    }

    button {
      border: 0;
      border-radius: 999px;
      background: var(--primary);
      color: #fff;
      font-weight: 700;
      font-size: 1rem;
      padding: 14px 22px;
      cursor: pointer;
      box-shadow: 0 12px 24px rgba(37, 99, 235, 0.25);
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 16px 28px rgba(37, 99, 235, 0.3);
      filter: brightness(1.02);
    }

    button:focus-visible,
    .choice input:focus-visible {
      outline: 3px solid rgba(37, 99, 235, 0.35);
      outline-offset: 2px;
    }

    .results {
      display: none;
      margin-top: 18px;
      padding: 16px 18px;
      border-radius: 16px;
      background: #ecfeff;
      color: #155e75;
      border: 1px solid #a5f3fc;
    }

    .results strong {
      display: block;
      margin-bottom: 6px;
    }

    @media (max-width: 640px) {
      body {
        padding: 20px 12px 28px;
      }

      .form-field {
        padding: 18px;
      }

      .actions {
        justify-content: stretch;
      }

      button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="page">
    <header class="hero">
      <div class="eyebrow">Quiz Challenge</div>
      <h1>Computer Languages Quiz</h1>
      <p class="subtitle">Choose any answers that apply for each question. This quiz uses multiple-select checkboxes so you can pick more than one answer per question.</p>
    </header>

    <form id="quiz-form">
      <div class="form-field">
        <h2 class="question-title">1. Which of these are programming languages?</h2>
        <p class="help-text">Select every option you think belongs in the programming languages category.</p>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q1" value="Python" /><span>Python</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="HTML" /><span>HTML</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="JavaScript" /><span>JavaScript</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="CSS" /><span>CSS</span></label>
        </div>
      </div>

      <div class="form-field">
        <h2 class="question-title">2. Which languages are commonly used for web development?</h2>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q2" value="JavaScript" /><span>JavaScript</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="Ruby" /><span>Ruby</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="C" /><span>C</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="SQL" /><span>SQL</span></label>
        </div>
      </div>

      <div class="form-field">
        <h2 class="question-title">3. Which of these are used to build software or systems?</h2>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q3" value="Java" /><span>Java</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="Kotlin" /><span>Kotlin</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="Markdown" /><span>Markdown</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="Go" /><span>Go</span></label>
        </div>
      </div>

      <div class="actions">
        <button type="submit">Submit Quiz</button>
      </div>

      <div class="results" id="results" aria-live="polite"></div>
    </form>
  </main>

  <script>
    const form = document.getElementById('quiz-form');
    const results = document.getElementById('results');

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const selected = [...form.querySelectorAll('input[type="checkbox"]:checked')];
      const grouped = selected.reduce((acc, input) => {
        acc[input.name] ||= [];
        acc[input.name].push(input.value);
        return acc;
      }, {});

      const summary = [1, 2, 3].map((number) => {
        const answers = grouped[`q${number}`] || [];
        return `Question ${number}: ${answers.length ? answers.join(', ') : 'No answers selected'}`;
      }).join('<br />');

      results.innerHTML = `<strong>Your selections</strong>${summary}`;
      results.style.display = 'block';
    });
  </script>
</body>
</html>
