 <body>
   <main class="page">
     <header class="hero">
       <div class="eyebrow">Quiz Challenge</div>
       <h1>Computer Languages Quiz</h1>
       <p class="subtitle">Choose any answers that apply for each question. This quiz uses multiple-select checkboxes so you can pick more than one answer per question.</p>
     </header>

     <form id="quiz-form">
       <div class="form-field">
         <h2 class="question-title">1. Which of these are programming languages?</h2>
         <p class="help-text">Select every option you think belongs in the programming languages category.</p>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q1" value="Python" /><span>Python</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="HTML" /><span>HTML</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="JavaScript" /><span>JavaScript</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="CSS" /><span>CSS</span></label>
         </div>
       </div>

       <div class="form-field">
         <h2 class="question-title">2. Which languages are commonly used for web development?</h2>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q2" value="JavaScript" /><span>JavaScript</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="Ruby" /><span>Ruby</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="C" /><span>C</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="SQL" /><span>SQL</span></label>
         </div>
       </div>

       <div class="form-field">
         <h2 class="question-title">3. Which of these are used to build software or systems?</h2>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q3" value="Java" /><span>Java</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="Kotlin" /><span>Kotlin</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="Markdown" /><span>Markdown</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="Go" /><span>Go</span></label>
         </div>
       </div>

       <div class="actions">
         <button type="submit">Submit Quiz</button>
       </div>

       <div class="results" id="results" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const form = document.getElementById('quiz-form');
     const results = document.getElementById('results');

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const selected = [...form.querySelectorAll('input[type="checkbox"]:checked')];
       const grouped = selected.reduce((acc, input) => {
         acc[input.name] ||= [];
         acc[input.name].push(input.value);
         return acc;
       }, {});

       const summary = [1, 2, 3].map((number) => {
         const answers = grouped[`q${number}`] || [];
         return `Question ${number}: ${answers.length ? answers.join(', ') : 'No answers selected'}`;
       }).join('<br />');

       results.innerHTML = `<strong>Your selections</strong>${summary}`;
       results.style.display = 'block';
     });
   </script>
